import type { GoldenItem } from "./schema.ts";

/**
 * Build golden/ATTRIBUTION.md from the items, so the attribution the licences require
 * (title, author, source, licence, changes made) can never drift from the data.
 */
export function attributionMarkdown(items: GoldenItem[]): string {
  const lines = [
    "# Attribution",
    "",
    "Generated by `bun run attribution` from each item's `item.yaml`. Do not edit by hand.",
    "",
    "Each item folder holds a copy of the source text in three forms (`source.html`, `source.txt`,",
    "`expected-clean.md`) and annotations (`item.yaml`). Changes made to every source: images, video,",
    "interactive embeds and footnotes removed; HTML attributes stripped; in `expected-clean.md`, reference",
    "lists and empty sections removed and sub/superscripts written as Unicode characters.",
    "The annotations are a derivative work and are shared under the same licence as their source.",
    "",
    "| Item | Title | Author(s) | Source | Licence |",
    "| --- | --- | --- | --- | --- |",
  ];
  for (const i of [...items].sort((a, b) => a.id.localeCompare(b.id))) {
    const s = i.source;
    const cell = (v: string) => v.replace(/\|/g, "\\|");
    lines.push(
      `| ${i.id} | ${cell(i.title)} | ${cell(s.creators.join(", ") || "unknown")} | ${s.url ? `[${s.type}](${s.url})` : s.type}, retrieved ${s.retrieved} | [${s.licence.id}](${s.licence.url}) |`,
    );
  }
  return lines.join("\n") + "\n";
}
